descriptor.templateCss:
.vent-demo-root h2,.vent-demo-root h3{font-weight:700;line-height:normal}
.vent-demo-root p{line-height:normal}
.vent-demo-root :where(b,strong){font-weight:700}
.vent-demo-root :where(table,th,td){font-family:inherit;font-size:inherit}
:root,.vent-demo-root{--bg:#0c1622;--panel:#152737;--input:#203747;--border:#345163;--text:#edf5f9;--sub:#aec4d1;--teal:#00d4e0;--ok:#2ee6a8;--warn:#ffc857;--danger:#ff3b42;--off:#607d8b;font-family:Arial,"Helvetica Neue",sans-serif;color:var(--text);background:var(--bg)}
*{box-sizing:border-box}
.loading{color:var(--sub)}
.vent-header,.panel,.kpi{background:var(--panel);border:1px solid var(--border);border-radius:6px}
.vent-header{overflow:hidden}
.vent-header__top{height:48px;display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:1px solid var(--border)}
.vent-header__title{font-size:18px;color:var(--teal)}
.vent-header__scope{margin-left:auto;color:var(--sub);white-space:nowrap}
.demo-badge{padding:4px 8px;border:1px solid var(--warn);border-radius:4px;color:var(--warn);font-size:12px}
.state-tabs{min-height:48px;display:flex;align-items:stretch;overflow-x:auto;background:var(--bg)}
.state-tabs a{display:flex;align-items:center;min-height:44px;padding:8px 14px;border-bottom:2px solid transparent;color:var(--text);text-decoration:none;white-space:nowrap}
.state-tabs a.active{color:var(--teal);border-bottom-color:var(--teal)}
.view{display:grid;gap:10px;margin-top:10px}
.kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.kpi{min-height:112px;padding:12px}
.kpi__head{display:flex;align-items:center;gap:8px;color:var(--sub);font-size:13px}
.kpi__icon{display:grid;place-items:center;width:24px;height:24px;border:1px solid var(--teal);border-radius:6px;color:var(--teal)}
.kpi__value{display:block;margin:9px 0 4px;font-size:26px;font-weight:600;font-variant-numeric:tabular-nums}
.kpi__quality,.muted{color:var(--sub);font-size:12px}
.quality-STALE,.status-WARNING{color:var(--warn)}
.quality-OFFLINE,.status-MAJOR,.status-FAULT{color:var(--danger)}
.quality-UNKNOWN,.status-UNKNOWN{color:var(--sub)}
.quality-CURRENT,.status-ONLINE,.status-RUNNING{color:var(--ok)}
.overview-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,.85fr);gap:10px}
.panel{padding:14px;min-width:0}
.panel__head{display:flex;justify-content:space-between;gap:12px;align-items:start;padding-bottom:10px;border-bottom:1px solid var(--border)}
.panel__head h2{margin:0;font-size:17px}
.panel__head p{margin:3px 0 0;color:var(--sub);font-size:12px}
.barn-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:9px;margin-top:12px}
.barn-card{appearance:none;min-height:108px;padding:11px;text-align:left;background:var(--bg);color:var(--text);border:1px solid var(--border);border-radius:6px;cursor:pointer}
.barn-card:hover,.barn-card:focus-visible{outline:2px solid var(--teal);outline-offset:-2px}
.barn-card b{display:block;font-size:16px;margin-bottom:9px}
.barn-card span{display:block;font-size:12px;line-height:1.55}
.alarm-list{display:grid;gap:8px;margin-top:12px}
.alarm-mini{padding:9px;border-left:3px solid var(--warn);background:var(--bg)}
.alarm-mini.MAJOR{border-color:var(--danger)}
.alarm-mini b,.alarm-mini small{display:block}
.alarm-mini small{margin-top:4px;color:var(--sub)}
.detail-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(270px,.7fr);gap:10px}
.synoptic{overflow-x:auto;overscroll-behavior-x:contain}
.synoptic svg{display:block;min-width:760px;width:100%;height:auto}
.pipe{fill:none;stroke:#86a9bc;stroke-width:3}
.zone{fill:var(--bg);stroke:var(--border);stroke-width:2}
.fan circle,.pump rect,.louver rect{fill:var(--input);stroke:var(--ok);stroke-width:3}
.fan.FAULT circle{stroke:var(--danger)}
.fan.UNKNOWN circle,.pump.UNKNOWN rect{stroke:var(--sub);stroke-dasharray:5}
.svg-label{fill:var(--text);font-size:13px;text-anchor:middle}
.svg-sub{fill:var(--sub);font-size:11px;text-anchor:middle}
.equipment-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:10px}
.equipment-card{padding:9px;background:var(--bg);border:1px solid var(--border);border-radius:5px}
.equipment-card small,.equipment-card b{display:block}
.equipment-card small{color:var(--sub);margin-bottom:4px}
.controller-summary{display:grid;gap:9px}
.summary-row{display:flex;justify-content:space-between;gap:12px;padding:10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}
.summary-row span{color:var(--sub)}
.notice{padding:10px;border-left:3px solid var(--warn);background:rgba(255,200,87,.08);color:var(--sub);font-size:12px}
.chart-wrap{overflow-x:auto}
.chart{display:block;min-width:720px;width:100%;height:310px}
.chart .grid{stroke:var(--border);stroke-width:1}
.chart text{fill:var(--sub);font-size:11px}
.chart .inside{fill:none;stroke:var(--teal);stroke-width:3}
.chart .outside{fill:none;stroke:var(--warn);stroke-width:3}
.chart .humidity{fill:none;stroke:#6aa9ff;stroke-width:3}
.legend{display:flex;gap:16px;flex-wrap:wrap;color:var(--sub);font-size:12px}
.legend i{display:inline-block;width:14px;height:3px;margin-right:5px;vertical-align:middle}
.table-wrap{overflow-x:auto}
.data-table{width:100%;min-width:720px;border-collapse:collapse}
.data-table th,.data-table td{padding:12px;text-align:left;border-bottom:1px solid var(--border)}
.data-table th{color:var(--teal);font-size:12px}
.pill{display:inline-block;padding:3px 7px;border:1px solid currentColor;border-radius:4px;font-size:11px;font-weight:700}
.footer{display:flex;justify-content:space-between;gap:10px;color:var(--sub);font-size:12px;padding:2px 4px}
.error{padding:18px;border:1px solid var(--danger);color:var(--danger)}
@media(max-width:1100px){.kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.overview-grid,.detail-layout{grid-template-columns:1fr}}
@media(max-width:700px){.vent-header__top{padding:0 10px}.vent-header__title{font-size:16px}.vent-header__scope{display:none}.state-tabs a{padding:7px 10px;font-size:13px}.kpi-grid{grid-template-columns:1fr;gap:8px}.kpi{min-height:96px}.overview-grid{display:block}.overview-grid>.panel+.panel{margin-top:8px}.panel{padding:11px}.barn-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.equipment-grid{grid-template-columns:1fr}.footer{flex-direction:column}}
.barn-card em{display:inline-block;margin-left:4px;padding:1px 4px;border:1px solid var(--warn);border-radius:3px;color:var(--warn);font-size:9px;font-style:normal;vertical-align:2px}
.detail-main{align-self:start}
.controller-panel{align-self:stretch}
.controller-summary{gap:7px}
.subsection-title{margin:14px 0 7px;padding-top:11px;border-top:1px solid var(--border);font-size:13px;color:var(--teal);text-transform:uppercase;letter-spacing:.5px}
.secondary-metrics{display:grid;gap:7px}
.secondary-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}
.secondary-row>span{color:var(--sub)}
.secondary-row small{display:block;margin-top:2px;font-size:10px}
.secondary-row b{font-variant-numeric:tabular-nums}
.compact-notice{margin-top:9px}
.text-link{display:inline-block;margin-top:11px;color:var(--teal);text-decoration:none}
.text-link:hover{text-decoration:underline}
.equipment-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}
.synoptic svg{min-width:760px}
.chart .perceived{fill:none;stroke:#ff8fcf;stroke-width:3}
.demo-limit{margin:0;padding:2px 4px;color:var(--sub);font-size:11px}
.barn-card em.identity-PILOT{border-color:var(--teal);color:var(--teal)}
.barn-card em.identity-SYNTHETIC{border-color:var(--sub);color:var(--sub)}
.fan.STOPPED circle{stroke:var(--off)}
.louver.quality-STALE rect{stroke:var(--warn)}
.louver.quality-OFFLINE rect{stroke:var(--danger)}
.louver.quality-UNKNOWN rect{stroke:var(--sub);stroke-dasharray:5}
.svg-sub.state-RUNNING{fill:var(--ok)}
.svg-sub.state-FAULT{fill:var(--danger)}
.status-STOPPED{color:var(--text)}
.synoptic,.chart-wrap,.table-wrap{scrollbar-color:var(--border) transparent}
@media(max-width:1100px){.equipment-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.controller-panel{align-self:start}}
@media(max-width:700px){.equipment-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.secondary-row{padding:8px}.demo-limit{padding:3px 1px}}
.vent-demo-root{display:block;height:100%;overflow-y:auto;overflow-x:hidden;padding:12px;background:var(--bg);font-size:14px;line-height:normal}
.vent-demo-root>.view:first-of-type,.vent-demo-root .vent-header+.view{margin-top:10px}
.vent-demo-root :where(h2,h3,p){letter-spacing:normal}
.vent-demo-root a{border-bottom:0;text-decoration:none}
.vent-demo-root .state-tabs a{border-bottom:2px solid transparent}
.vent-demo-root .state-tabs a.active{border-bottom-color:var(--teal)}
.vent-demo-root :where(button){font:inherit}
.vent-demo-root .vent-header__top{padding-right:64px}
@media(max-width:700px){.vent-demo-root{padding:8px}}

descriptor.controllerScript:
// SINH TỰ ĐỘNG bởi deploy/thingsboard/build_vent_demo.py (VENT-006). KHÔNG sửa trong Widget Editor.
// Demo fixture cô lập: không datasource, không telemetry, không RPC, không ghi attribute.
self.onInit = function () {
  var __vent = {};
(function (root) {
  "use strict";
  var QUALITY = ["CURRENT", "STALE", "OFFLINE", "UNKNOWN"];
  var BARN_IDENTITY = ["PILOT", "LIVE_BARN_SIMULATED_STATE", "SYNTHETIC"];
  var CANONICAL_MAP = {
    indoorTemperature01: "temperature_indoor_01", indoorTemperature02: "temperature_indoor_02",
    indoorTemperatureAvg: "temperature_indoor", outdoorTemperature: "temperature_outdoor",
    perceivedTemperature: "temperature_feel", relativeHumidity: "humidity",
    airSpeed: "air_speed", airFlow: "air_flow", waterConsumptionTotal: "water_consumption",
    operatingMode: "operation_mode", fanControlMode: "fan_control_mode",
    fanStage: "ventilation_stage", stageCount: "ventilation_stage_count",
    controllerOnline: "controller_online", dataQuality: "data_quality",
    roofInletPosition: "roof_louver_position", sideInletPosition: "side_louver_position"
  };
  var HISTORY_MAP = {
    indoorTemperatureAvg: "temperature_indoor", outdoorTemperature: "temperature_outdoor",
    perceivedTemperature: "temperature_feel", relativeHumidity: "humidity"
  };
  (function addEquipmentKeys() {
    for (var i = 1; i <= 6; i += 1) {
      var fan = String(i).padStart(2, "0");
      CANONICAL_MAP["fan" + fan + "Run"] = "fan_" + fan + "_run";
      CANONICAL_MAP["fan" + fan + "Fault"] = "fan_" + fan + "_fault";
    }
    for (var p = 1; p <= 2; p += 1) {
      var pump = String(p).padStart(2, "0");
      CANONICAL_MAP["coolingPump" + pump + "Run"] = "pump_" + pump + "_run";
      CANONICAL_MAP["coolingPump" + pump + "Fault"] = "pump_" + pump + "_fault";
    }
  }());
  function isMissing(value) { return value === null || value === undefined; }
  // Giữ nguyên false/0; chỉ null/undefined mới là "chưa có dữ liệu".
  function safeMetric(metric) {
    metric = metric && typeof metric === "object" ? metric : {};
    return { value: metric.value === undefined ? null : metric.value,
      unit: isMissing(metric.unit) ? "" : metric.unit,
      quality: QUALITY.indexOf(metric.quality) >= 0 ? metric.quality : "UNKNOWN",
      ts: metric.ts === undefined ? null : metric.ts };
  }
  function combinedQuality(runMetric, faultMetric) {
    var qualities = [runMetric.quality, faultMetric.quality];
    if (qualities.indexOf("OFFLINE") >= 0) return "OFFLINE";
    if (qualities.indexOf("STALE") >= 0) return "STALE";
    if (qualities.indexOf("UNKNOWN") >= 0) return "UNKNOWN";
    return "CURRENT";
  }
  // Suy diễn hiển thị demo; không khẳng định phản hồi vật lý đã được xác minh.
  function equipmentState(runMetric, faultMetric) {
    if (faultMetric.value === true) return "FAULT";
    if (faultMetric.value === false && runMetric.value === true) return "RUNNING";
    if (faultMetric.value === false && runMetric.value === false) return "STOPPED";
    return "UNKNOWN";
  }
  function equipment(metrics, canonicalPrefix, labelPrefix, count) {
    var rows = [];
    for (var i = 1; i <= count; i += 1) {
      var suffix = String(i).padStart(2, "0");
      var run = metrics[canonicalPrefix + suffix + "Run"], fault = metrics[canonicalPrefix + suffix + "Fault"];
      rows.push({ key: canonicalPrefix + suffix, label: labelPrefix + " " + suffix,
        run: run, fault: fault, state: equipmentState(run, fault),
        quality: combinedQuality(run, fault) });
    }
    return rows;
  }
  // Chỉ hiện mẫu số khi stageCount có thật; không tự suy 6/9.
  function stageDisplay(stageMetric, countMetric) {
    if (isMissing(stageMetric.value)) return "--";
    if (isMissing(countMetric.value)) return String(stageMetric.value);
    return String(stageMetric.value) + " / " + String(countMetric.value);
  }
  function controllerOnlineState(metric) {
    if (metric.value === true) return "ONLINE";
    if (metric.value === false) return "OFFLINE";
    return "UNKNOWN";
  }
  function mapHistory(row) {
    var mapped = { ts: row.ts, quality: isMissing(row.quality) ? "UNKNOWN" : row.quality };
    Object.keys(HISTORY_MAP).forEach(function (key) {
      var sample = row[HISTORY_MAP[key]];
      mapped[key] = sample === undefined ? null : sample;
    });
    return mapped;
  }
  // Nhà không khai báo danh tính rõ ràng bị coi là tổng hợp, không bao giờ là nhà live.
  function mapBarn(barn) {
    var copy = Object.assign({}, barn);
    if (BARN_IDENTITY.indexOf(copy.identity) < 0) copy.identity = "SYNTHETIC";
    copy.synthetic = copy.identity === "SYNTHETIC";
    return copy;
  }
  function createViewModel(raw) {
    if (!raw || raw.demo !== true) throw new Error("Fixture source must be explicitly marked demo");
    var latest = raw.latest || {}, metrics = {};
    Object.keys(CANONICAL_MAP).forEach(function (canonicalKey) {
      metrics[canonicalKey] = safeMetric(latest[CANONICAL_MAP[canonicalKey]]);
    });
    return { source: "fixture", demo: true, badgeLabel: raw.badgeLabel || "DEMO DATA",
      fixtureVersion: raw.fixtureVersion, generatedAt: raw.generatedAt, scope: raw.scope || {},
      summary: raw.summary || {}, barns: (raw.barns || []).map(mapBarn),
      metrics: metrics,
      controller: { online: controllerOnlineState(metrics.controllerOnline),
        stageDisplay: stageDisplay(metrics.fanStage, metrics.stageCount) },
      equipment: equipment(metrics, "fan", "Quạt", 6)
        .concat(equipment(metrics, "coolingPump", "Bơm làm mát", 2)),
      louvers: [Object.assign({key: "roofInletPosition", label: "Cửa chớp trần"}, metrics.roofInletPosition),
        Object.assign({key: "sideInletPosition", label: "Cửa chớp hông"}, metrics.sideInletPosition)],
      history: (raw.history || []).map(mapHistory),
      alarms: (raw.alarms || []).map(function (alarm) { return Object.assign({}, alarm); }) };
  }
  function FixtureSource(url) { this.url = url; }
  FixtureSource.prototype.load = function () {
    try { var request = new XMLHttpRequest(); request.open("GET", this.url, false); request.send(null);
      if (request.status !== 200) throw new Error("Fixture load failed");
      return Promise.resolve(createViewModel(JSON.parse(request.responseText)));
    } catch (error) { return Promise.reject(error); }
  };
  function ThingsBoardSource() {}
  ThingsBoardSource.prototype.load = function () { return Promise.reject(new Error("ThingsBoard source is intentionally unconfigured until VENT-002 is implementation-ready")); };
  root.VentilationAdapter = { createViewModel: createViewModel, equipmentState: equipmentState,
    stageDisplay: stageDisplay, safeMetric: safeMetric, mapHistory: mapHistory,
    CANONICAL_MAP: CANONICAL_MAP, FixtureSource: FixtureSource, ThingsBoardSource: ThingsBoardSource };
}(__vent));

(function (root) {
  "use strict";
  var STATES = ["default", "vent_detail", "vent_history", "vent_alarms"];
  var labels = {default: "Tổng quan", vent_detail: "Giám sát", vent_history: "Lịch sử", vent_alarms: "Cảnh báo"};
  var vm;
  function esc(value) { return String(value == null ? "" : value).replace(/[&<>"']/g, function (c) { return ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"})[c]; }); }
  function isMissing(value) { return value === null || value === undefined; }
  function normalizeState(id) { return STATES.indexOf(id) >= 0 ? id : "default"; }
  function metric(key) { return vm.metrics[key] || {value: null, unit: "", quality: "UNKNOWN"}; }
  function value(item) { return isMissing(item.value) ? "--" : esc(item.value) + (item.unit ? " <small>" + esc(item.unit) + "</small>" : ""); }
  function plainValue(item) { return isMissing(item.value) ? "--" : esc(item.value) + (item.unit ? " " + esc(item.unit) : ""); }
  function header(state) {
    return '<header class="vent-header"><div class="vent-header__top"><strong class="vent-header__title">SIBA · Thông gió</strong>' +
      '<span class="vent-header__scope">' + esc(vm.scope.farm) + ' · ' + esc(vm.scope.area) + '</span>' +
      '<b class="demo-badge">' + esc(vm.badgeLabel) + '</b></div><nav class="state-tabs" aria-label="Trạng thái dashboard">' +
      STATES.map(function (item) { return '<a href="#' + item + '" data-nav="' + item + '" class="' + (item === state ? 'active' : '') + '">' + labels[item] + '</a>'; }).join("") + '</nav></header>';
  }
  function kpi(label, key, icon) {
    var item = metric(key);
    return '<article class="kpi"><div class="kpi__head"><span class="kpi__icon">' + icon + '</span>' + label + '</div>' +
      '<b class="kpi__value">' + value(item) + '</b><span class="kpi__quality quality-' + item.quality + '">' + item.quality +
      (item.ts ? ' · ' + new Date(item.ts).toLocaleTimeString('vi-VN', {hour:'2-digit', minute:'2-digit'}) : '') + '</span></article>';
  }
  function summaryValue(key) { var item = vm.summary[key]; return isMissing(item) ? "--" : item; }
  function summaryKpi(label, key, icon) {
    return '<article class="kpi"><div class="kpi__head"><span class="kpi__icon">' + icon + '</span>' + label + '</div>' +
      '<b class="kpi__value">' + esc(summaryValue(key)) + '</b><span class="kpi__quality">DEMO SUMMARY</span></article>';
  }
  var IDENTITY_TAGS = {PILOT: ['PILOT · DEMO', 'Nhà pilot có thật; trạng thái thông gió là dữ liệu demo'],
    LIVE_BARN_SIMULATED_STATE: ['DEMO', 'Nhà có thật; hệ thông gió chưa xác minh, trạng thái mô phỏng'],
    SYNTHETIC: ['SYNTHETIC', 'Nhà tổng hợp chỉ để minh họa bố cục; không tồn tại']};
  function identityTag(barn) {
    var tag = IDENTITY_TAGS[barn.identity] || IDENTITY_TAGS.SYNTHETIC;
    return ' <em class="identity-' + esc(barn.identity) + '" title="' + esc(tag[1]) + '">' + esc(tag[0]) + '</em>';
  }
  function overview() {
    return '<section class="view"><div class="kpi-grid">' + summaryKpi('Tổng số nhà', 'barns', '⌂') +
      summaryKpi('Đang trực tuyến', 'online', '●') + summaryKpi('Cần chú ý', 'attention', '!') +
      summaryKpi('Cảnh báo đang mở', 'activeAlarms', '△') + '</div><div class="overview-grid"><section class="panel">' +
      '<div class="panel__head"><div><h2>Toàn trại</h2><p>Chọn một nhà để xem giám sát thông gió.</p></div><span class="muted">Trạng thái mọi nhà là mô phỏng</span></div>' +
      '<div class="barn-grid">' + vm.barns.map(function (barn) {
        return '<button class="barn-card" data-nav="vent_detail"><b>' + esc(barn.label) + identityTag(barn) + '</b>' +
          '<span class="status-' + barn.connectivity + '">' + barn.connectivity + '</span><span class="quality-' + barn.freshness + '">Dữ liệu: ' + barn.freshness + '</span>' +
          '<span>Chế độ: ' + esc(barn.mode) + '</span><span class="status-' + barn.alarm + '">Cảnh báo: ' + barn.alarm + '</span></button>';
      }).join('') + '</div></section><section class="panel"><div class="panel__head"><div><h2>Cảnh báo ưu tiên</h2>' +
      '<p>Chỉ xem; không có thao tác vòng đời.</p></div><a href="#vent_alarms" data-nav="vent_alarms" class="muted">Xem tất cả →</a></div><div class="alarm-list">' +
      vm.alarms.map(function (alarm) { return '<article class="alarm-mini ' + alarm.severity + '"><b>' + esc(alarm.type) + '</b><span>' +
        esc(alarm.message) + '</span><small>' + esc(alarm.originator) + '</small></article>'; }).join('') + '</div></section></div>' + footer() + '</section>';
  }
  function equipmentCards() {
    return vm.equipment.map(function (item) { return '<article class="equipment-card"><small>' + esc(item.label) + '</small>' +
      '<b class="status-' + esc(item.state) + '">' + esc(item.state) + '</b><span class="muted">Dữ liệu: ' + esc(item.quality) + '</span></article>'; }).join('');
  }
  function louverShape(item, y) {
    return '<g class="louver quality-' + esc(item.quality) + '"><rect x="300" y="' + y + '" width="300" height="24" rx="4"/><text class="svg-sub" x="450" y="' + (y + 16) + '">' +
      esc(item.label) + ' · ' + plainValue(item) + ' · ' + esc(item.quality) + '</text></g>';
  }
  function synoptic() {
    var fans = vm.equipment.slice(0, 6);
    return '<div class="synoptic" role="region" aria-label="Sơ đồ thông gió có thể cuộn ngang"><svg viewBox="0 0 900 244" role="img" aria-label="Sơ đồ thông gió chỉ đọc nhà ' + esc(vm.scope.selectedBarn) + '">' +
